export const instancesCommand = defineCommand({
  description: 'List the running instances of an application',
  since: null,
  options: {
    alias: aliasOption,
    app: appIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [],
  async handler(options) {
    const { alias, app: appIdOrName, format } = options;
    const { ownerId, appId } = await Application.resolveId(appIdOrName, alias);

    const instances = await listInstances({ ownerId, appId, onlyRunning: true });

    // Build VMs last, then by instance number (missing at the very beginning of booting), most recent first
    const sortedInstances = instances.toSorted((a, b) => {
      return (
        Number(a.isBuildVm) - Number(b.isBuildVm) ||
        (a.instanceNumber ?? Infinity) - (b.instanceNumber ?? Infinity) ||
        b.createdAt.localeCompare(a.createdAt)
      );
    });

    switch (format) {
      case 'json': {
        Logger.printJson(sortedInstances);
        break;
      }
      case 'human':
      default: {
        if (sortedInstances.length === 0) {
          Logger.println('No running instances found for this application');
          return;
        }

        const head = ['NUMBER', 'ID', 'NAME', 'STATE', 'FLAVOR', 'CREATION DATE'];
        const lines = sortedInstances.map((instance) => [
          instance.isBuildVm ? 'build' : (instance.instanceNumber ?? '?'),
          instance.id,
          instance.name ?? '?',
          instance.state,
          instance.flavor ?? '?',
          instance.createdAt,
        ]);

        Logger.println(formatTable([head, ...lines]));
      }
    }
  },
});
